namespace Tests;
public class AdminCategoriesTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Admin_categories_hierarchy_required_details_slug_and_validation()
    {
        var admin=await Admin();var support=await Staff(admin,"catsupport@example.test","support");Assert.Equal(403,(await support.Get("/api/admin/categories")).Status);Assert.NotEmpty((await admin.Get("/api/admin/categories/requirements")).Json["options"]!.AsObject());
        var r=await admin.Post("/api/admin/categories",new{name="Synthetic Root",commission_bps=500,default_gst_bps=25,required_details=new[]{"warranty","brand","brand"}});Assert.True(r.Status==201,r.ToString());var root=r.Json["id"]!.GetValue<string>();Assert.Equal("synthetic-root",r.Json["slug"]!.GetValue<string>());Assert.Equal(new[]{"brand","warranty"},r.Json["required_details"]!.AsArray().Select(x=>x!.GetValue<string>()));
        r=await admin.Post("/api/admin/categories",new{name="Synthetic Child",parent_id=root,commission_bps=500,default_gst_bps=4000,position=2});Assert.True(r.Status==201,r.ToString());var child=r.Json["id"]!.GetValue<string>();Assert.Equal("category_cycle",(await admin.Put("/api/admin/categories/"+root,new{name="Rename Root",parent_id=child,commission_bps=500,default_gst_bps=500})).ErrorCode);
        r=await admin.Put("/api/admin/categories/"+child,new{name="Renamed Child",commission_bps=1000,default_gst_bps=300,is_active=false,position=1});Assert.Equal(200,r.Status);Assert.Equal("synthetic-child",r.Json["slug"]!.GetValue<string>());Assert.False(r.Json["is_active"]!.GetValue<bool>());
        r=await admin.Post("/api/admin/categories",new{name="Synthetic Root",commission_bps=500,default_gst_bps=500});Assert.True(r.Status==201,r.ToString());Assert.StartsWith("synthetic-root-",r.Json["slug"]!.GetValue<string>());
        Assert.Equal("invalid_parent",(await admin.Post("/api/admin/categories",new{name="Bad Parent",parent_id=Guid.NewGuid(),commission_bps=500,default_gst_bps=500})).ErrorCode);Assert.Equal("invalid_gst",(await admin.Post("/api/admin/categories",new{name="Bad GST",commission_bps=500,default_gst_bps=111})).ErrorCode);Assert.Equal("invalid_return_window",(await admin.Post("/api/admin/categories",new{name="Bad Window",commission_bps=500,default_gst_bps=500,return_window_days=3,min_return_window_days=5})).ErrorCode);Assert.Equal(422,(await admin.Post("/api/admin/categories",new{name="Missing required"})).Status);Assert.Equal(422,(await admin.Post("/api/admin/categories",new{name="Bad Required",commission_bps=500,default_gst_bps=500,required_details=new[]{"nonsense"}})).Status);Assert.Equal(404,(await admin.Put("/api/admin/categories/"+Guid.NewGuid(),new{name="Missing category",commission_bps=500,default_gst_bps=500})).Status);
        r=await admin.Get("/api/admin/categories");Assert.Equal(3,r.Json.AsArray().Count);Assert.Equal(child,r.Json[2]!["id"]!.GetValue<string>());
    }
    [Fact]public async Task Admin_category_minimum_propagates_atomically_and_parents_with_products_rejected()
    {
        var admin=await Admin();var seller=await LoginPhone("9890000033");var r=await seller.Post("/api/seller/register",new{display_name="Category Test Store"});var sid=r.Json["id"]!.GetValue<string>();r=await admin.Post("/api/admin/categories",new{name="Product Category",commission_bps=500,default_gst_bps=500});var cat=r.Json["id"]!.GetValue<string>();var p=Guid.NewGuid();
        await ApiFactory.DbExecAsync("INSERT INTO products (id,seller_id,category_id,title,slug,brand,description,highlights,specs,hsn_code,gst_bps,country_of_origin,return_window_days,status,rejection_reason,price_from,mrp_from,in_stock,rating_avg,rating_count,sold_count,details) VALUES (@p,@sid,@cat,'Synthetic Product','synthetic-product','Acme','Synthetic description','[]','{}','6205',500,'India',2,'draft','',10000,20000,1,0,0,0,'{}')",new{p,sid,cat});
        Assert.Equal("parent_has_products",(await admin.Post("/api/admin/categories",new{name="Bad Child",parent_id=cat,commission_bps=500,default_gst_bps=500})).ErrorCode);
        r=await admin.Put("/api/admin/categories/"+cat,new{name="Product Category",commission_bps=1000,default_gst_bps=500,min_return_window_days=5});Assert.True(r.Status==200,r.ToString());Assert.Equal(5,await ApiFactory.DbScalarAsync<int>("SELECT return_window_days FROM products WHERE id=@p",new{p}));
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_cat_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action IN ('category.create','category.update') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic category rollback'; END IF; END");try{Assert.Equal(500,(await admin.Put("/api/admin/categories/"+cat,new{name="Should Rollback",commission_bps=1000,default_gst_bps=500,min_return_window_days=7})).Status);Assert.Equal(5,await ApiFactory.DbScalarAsync<int>("SELECT return_window_days FROM products WHERE id=@p",new{p}));Assert.Equal("Product Category",await ApiFactory.DbScalarAsync<string>("SELECT name FROM categories WHERE id=@cat",new{cat}));Assert.Equal(500,(await admin.Post("/api/admin/categories",new{name="Rolled Back",commission_bps=500,default_gst_bps=500})).Status);Assert.Equal(1,await ApiFactory.DbScalarAsync<int>("SELECT COUNT(*) FROM categories"));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_cat_fail");}
        Assert.Equal(200,(await admin.Put("/api/admin/categories/"+cat,new{name="Product Category",commission_bps=500,default_gst_bps=500,min_return_window_days=1})).Status);Assert.Equal(5,await ApiFactory.DbScalarAsync<int>("SELECT return_window_days FROM products WHERE id=@p",new{p}));
    }
}
